// Copy the static files next to the compiled JavaScript so dist/ is the site root.
import { cp, mkdir, rm } from "node:fs/promises";

await mkdir("dist", { recursive: true });
await Promise.all(
  ["index.html", "styles.css"].map((file) => cp(file, `dist/${file}`, { force: true })),
);

// data/ is generated by `npm run feed`; it is optional so local builds still
// work (the page then falls back to the live proxy).
await rm("dist/data", { recursive: true, force: true });
try {
  await cp("data", "dist/data", { recursive: true, force: true });
  console.log("copied index.html, styles.css and data/ to dist/");
} catch (error) {
  if (error.code !== "ENOENT") throw error;
  console.log("copied index.html and styles.css to dist/ (no data/ snapshot)");
}
